/**
 * New chains and tokens: the bot learns them from Meson's live table, without a code change or restart.
 * In a file of its own, because the live table's "read at most every so often" timer is shared within a file.
 */
// ----- Contents (generated by `npm run index` — do not edit) -----
// L21   Helpers
// L32     stubBundle()
// L46   Tests
// ----- end of contents -----

import test from 'node:test'
import assert from 'node:assert/strict'
import { useFakeSettings, makeWorld, swapId, swapRecord, encodedSwap, json, sleep, MOVING } from './helpers.mjs'

useFakeSettings()
const { lookupSwap, getSwaps, refreshPresets } = await import('../src/meson.js')
const { fetchLiveChains, chainName, tokenSymbol } = await import('../src/presets.js')
const { watchSwap, stopWatchingChannel } = await import('../src/watch.js')
const { getTicket } = await import('../src/ticket-state.js')

// =============================================================================
//   Helpers
// =============================================================================

/** Enough chains for the live table to pass its "was the bundle misread?" check. */
const FAKE_FILLER_CHAINS = Array.from({ length: 40 }, (_, i) => `{"id":"filler${i}","name":"Filler ${i}","shortSlip44":"0x${(0x4000 + i).toString(16)}","tokens":[]}`).join(',')

/** A chain Meson has just added, as it appears in the explorer's bundle. */
const NEW_CHAIN = '{"id":"newc","name":"Brand New\\xb2 Chain","shortSlip44":"0x7777","explorer":"https://scan.example","addressFormat":"ethers","tokens":[{"tokenIndex":9,"symbol":"NEWT"}]}'

/** Replace fetch with a fake Meson whose bundle holds `chains`; `failChunk` makes the chunk download fail. Swap requests answer with `encoded`. */
function stubBundle ({ chains, failChunk = false, encoded }) {
  globalThis.fetch = async (url) => {
    const u = String(url)
    if (u.includes('rpcs.meson.fi')) return json({ data: {} })
    if (u.endsWith('/')) return new Response('<script src="/_next/static/chunks/a.js"></script>')
    if (u.endsWith('a.js')) return failChunk ? new Response('nope', { status: 500 }) : new Response(`x=[${chains}]`)
    const q = u.match(/\/search\?q=(.+)$/)
    if (q) return json({ result: { swapId: q[1] } })
    const ids = u.match(/\/api\/v1\/swap\/(.+)$/)[1].split(/,|%2C/)
    const records = ids.map((id) => swapRecord(id, MOVING, encoded))
    return json({ result: ids.length > 1 ? records : records[0] })
  }
}

// =============================================================================
//   Tests
// =============================================================================

test('a table read fails as a whole if any chunk cannot be read', async () => {
  stubBundle({ chains: `${FAKE_FILLER_CHAINS},${NEW_CHAIN}`, failChunk: true })
  await assert.rejects(fetchLiveChains({ timeoutMs: 1000 }))
})

test('a truncated table is refused', async () => {
  stubBundle({ chains: NEW_CHAIN })
  await assert.rejects(fetchLiveChains({ timeoutMs: 1000 }), /refusing/)
})

test('a failed read keeps the table in use', async () => {
  const before = chainName('0x02ca')
  stubBundle({ chains: '', failChunk: true })
  await refreshPresets()
  assert.equal(chainName('0x02ca'), before)
})

test('a swap on a brand-new chain and token is named correctly the first time it is shown', async (t) => {
  // The previous test's read counts towards the gap between reads; the wait is what the live bot would see.
  t.mock.timers.enable({ apis: ['Date'], now: Date.now() + 11 * 60 * 1000 })
  assert.equal(chainName('0x7777'), 'Unknown chain (0x7777)')
  const encoded = encodedSwap({ outChain: '7777', outToken: '09' })
  stubBundle({ chains: `${FAKE_FILLER_CHAINS},${NEW_CHAIN}`, encoded })
  const swap = await lookupSwap(swapId(1))
  assert.equal(swap.to.chain, 'Brand New² Chain')
  assert.equal(swap.to.token, 'NEWT')
  assert.equal(swap.to.addressUrl, 'https://scan.example/address/b')
  t.mock.timers.reset()
})

test('a merge removes nothing, and live names win', async () => {
  stubBundle({ chains: `${FAKE_FILLER_CHAINS},${NEW_CHAIN.replace('NEWT', 'RENAMED')}` })
  await refreshPresets()
  assert.equal(tokenSymbol('0x7777', 9), 'RENAMED')
  assert.equal(chainName('0x02ca').startsWith('Unknown'), false, 'a chain missing from the live table stays known')
})

test('an embed posted with an unknown name is corrected once the table has it', async () => {
  const id = swapId(2)
  const encoded = encodedSwap({ outChain: '7778', outToken: '01' })
  // The read within the gap does not run, so the swap is first seen with an unknown chain.
  stubBundle({ chains: '', failChunk: true, encoded })
  const latest = (await getSwaps([id])).get(id)
  assert.equal(latest.to.chain, 'Unknown chain (0x7778)')

  const world = makeWorld('p1')
  const embed = world.message(1, world.me)
  const ticket = getTicket(world.channel.id)
  const entry = { n: 1, swapId: id, message: embed, latest }
  ticket.swaps.push(entry)
  await watchSwap(ticket, entry)

  const later = NEW_CHAIN.replace('0x7777', '0x7778').replace('"tokenIndex":9', '"tokenIndex":1').replace('Brand New\\xb2 Chain', 'Later Chain')
  stubBundle({ chains: `${FAKE_FILLER_CHAINS},${later}`, encoded })
  await refreshPresets()
  await sleep(2000)
  assert.equal(entry.latest.to.chain, 'Later Chain')
  assert.ok(embed.edits >= 1)
  assert.ok(embed.embeds[0].data.fields.some((f) => f.value.includes('Later Chain')))
  stopWatchingChannel('p1')
})
